 50	const askAfterConnect = async (url: string, outbound: unknown): Promise<{connected: Frame; frames: Frame[]}> => {
 51	  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, 't']);
 52	  clients.push(client);
 53	  const frames: Frame[] = [];
 54	  let connected: Frame = {type: ''};
 55	  await new Promise<void>(resolve => {
 56	    client.on('message', raw => {
 57	      const frame = JSON.parse(String(raw)) as Frame;
 58	      if (frame.type !== 'connected') {
 59	        if (frame.type === 'pong') {
 60	          resolve();
 61	          return;
 62	        }
 63	        frames.push(frame);
 64	        return;
 65	      }
 66	      connected = frame;
 67	      client.send(typeof outbound === 'string' ? outbound : JSON.stringify(outbound));
 68	      client.send(JSON.stringify({type: 'ping', timestamp: 1}));
 69	    });
 70	  });
 71	  return {connected, frames};
 72	};
